            0 0 34px rgba(217,208,255,.16)!important;
        opacity:1!important;
        visibility:visible!important;
        writing-mode:horizontal-tb!important;
    }

    .custom-char-card[data-forms] .custom-char-art{
        cursor:pointer!important;
    }

    .custom-char-card[data-forms]:hover .custom-char-art{
        box-shadow:
            inset 0 0 0 1px rgba(255,255,255,.32),
            inset 0 0 38px rgba(217,208,255,.12),
