        visibility:visible!important;
        background:linear-gradient(180deg,#1a1a43,#070715)!important;
        writing-mode:horizontal-tb!important;
    }

    .custom-char-card:hover .custom-char-art img{
        transform:scale(1.052);
        filter:saturate(1.08) contrast(1.1) brightness(1)!important;
    }

    /* 切换淡出态：透明度/模糊/位移均通过 transition 在 !important 计算值之间插值，
       因此即使基础 img 的 opacity、filter 带 !important 也能正常播放动画。
       JS 先加 .custom-art-switching（淡出），换图后移除（自动淡入）。 */
    .custom-char-art.custom-art-switching img{
        opacity:0!important;
        transform:scale(1.07) translateY(16px) rotate(.6deg)!important;
        filter:blur(9px) saturate(1.14) contrast(1.04) brightness(1.18)!important;
    }

    /* 切换瞬间让星纹高光闪一下，增强“档案翻页”的魔法感（:before 无 !important，可自由过渡） */
    .custom-char-art.custom-art-switching:before{
        opacity:1;
        filter:brightness(1.85) saturate(1.25);
    }

    .custom-char-art:before{
