            linear-gradient(180deg,rgba(5,5,18,.02) 38%,rgba(5,5,18,.74));
        background-size:88px 88px,100% 100%,100% 100%,100% 100%;
        opacity:.82;
        transition:opacity .42s ease,filter .42s ease;
    }

